var n=`1410-panikeke`;var i=`world-1410`;var t=`WS`;var r=`oceania`;var l=6;var s=39;var o={en:`Panikeke`,ua:`Панікеке`};var u={en:`Panikeke are Samoan small round fried doughnuts; this is a straightforward sweet batter version.`,ua:`Паніке́ке, самоанські круглі пончики, смажені в олії; тут наведено просту версію із солодкого тіста.`};var g=[{en:`Whisk flour, sugar, baking powder and salt in a bowl.`,ua:`Змішайте вінчиком борошно, цукор, розпушувач і сіль.`,t:[`mixing`],m:4,i:[[`all-purpose-flour`,320,`g`],[`caster-sugar`,80,`g`],[`baking-powder`,12,`g`],[`sea-salt`,3,`g`]]},{en:`Pour in water and vanilla; mix to a thick sticky batter. Let stand 10 minutes.`,ua:`Влийте воду та ваніль, перемішайте до густого липкого тіста. Залиште на 10 хвилин.`,t:[`mixing`],m:10,i:[[`water`,275,`ml`],[`vanilla-extract`,5,`ml`]]},{en:`Heat frying oil to 170–175°C in a deep, stable pan. Carefully drop small spoonfuls of batter in batches; fry 4–5 minutes, turning, until deeply golden and cooked in the centre.`,ua:`Нагрійте олію у глибокій стійкій каструлі до 170–175°C. Обережно опускайте невеликі ложки тіста порціями; смажте 4–5 хвилин, перевертаючи, до золотистого кольору та повної готовності всередині.`,t:[`deep-frying`],m:20,i:[[`vegetable-oil-neutral`,750,`ml`]]},{en:`Drain on a rack or paper, cool slightly, and serve warm.`,ua:`Викладіть на решітку або папір, трохи остудіть і подавайте теплими.`,t:[`draining`],m:5,i:[]}];var d={slug:n,id:i,country:`WS`,region:r,servings:6,minutes:39,title:o,text:u,steps:g};export{t as country,d as default,i as id,s as minutes,r as region,l as servings,n as slug,g as steps,u as text,o as title};